import './style.css';
import { site } from '../config/site.js';
import { presets, presetPixels } from '../presets/index.js';
import { calculateResizeDimensions, validateImageFile, nextQualityRange, targetStatus } from './processors/imageMath.js';
const $ = (s, p=document) => p.querySelector(s); const app=$('#app');
const route = (path = '') => new URL(path ? `${path}/` : '', document.baseURI).pathname;
const tools=[
['photo-resizer','Photo Resizer','Photo','Resize, crop and tune images in pixels, cm or inches.'],['photo-compressor','Photo Compressor','Photo','Reduce JPEG size with a target KB setting.'],['photo-cropper','Photo Cropper','Photo','Crop, rotate and export a clean image.'],['passport-photo-maker','Passport Photo Maker','Government','Prepare a passport-sized photo with editable dimensions.'],['pan-photo-resizer','PAN Photo Maker','Government','Start from a commonly used PAN photo size.'],['aadhaar-photo-resizer','Aadhaar Photo Resizer','Government','Resize a photo for your application.'],['visa-photo-maker','Visa Photo Maker','Government','Make a 2 × 2 inch visa-style image.'],['signature-resizer','Signature Resizer','Signature','Trim whitespace, resize and compress a signature.'],['signature-compressor','Signature Compressor','Signature','Lower a signature file size locally.'],['pan-signature-resizer','PAN Signature Maker','Signature','Start with a commonly used signature specification.'],['jpg-to-png','JPG to PNG','Image','Convert JPEG images to PNG.'],['png-to-jpg','PNG to JPG','Image','Convert PNG images to JPEG.'],['jpg-to-webp','JPG to WEBP','Image','Convert images to compact WEBP.'],['image-resize','Image Resize','Image','Set exact dimensions and export.'],['image-compressor','Image Compressor','Image','Compress photos for fast uploads.'],['jpg-to-pdf','JPG to PDF','PDF','Create downloadable image PDFs locally.'],['image-to-pdf','Image to PDF','PDF','Turn image files into downloadable PDF documents.'],['document-image-compressor','Document Image Compressor','PDF','Shrink scanned document images.']];
const toolFor=(slug)=>tools.find(x=>x[0]===slug) || tools[0];
function header(){return `<div class="top"><div class="wrap"><strong>Free tools. No account.</strong><span class="privacy">${site.privacyMessage}</span></div></div><nav class="wrap nav"><a class="brand" href="${route()}">${site.name}<span style="color:var(--accent)">.</span></a><div class="navlinks"><a href="${route('tools')}">All tools</a><a href="${route('privacy')}">Privacy</a><a href="${route('about')}">About</a><select class="lang" aria-label="Language"><option>English</option><option disabled>हिन्दी (soon)</option></select></div></nav>`}
function footer(){return `<footer><div class="wrap"><strong class="brand">${site.name}.</strong><p>Your practical browser-based file toolkit.</p><p><a href="${route('about')}">About</a><a href="${route('privacy')}">Privacy</a><a href="${route('terms')}">Terms</a><a href="${route('contact')}">Contact</a><a href="${route('disclaimer')}">Disclaimer</a></p></div></footer>`}
function ads(name){return `<aside class="ad" aria-label="Advertisement">Advertisement space · ${name}</aside>`}
function cards(list=tools){return `<div class="grid">${list.map(([s,n,c,d])=>`<a class="card tool-card" href="${route(s)}"><span class="tag">${c}</span><h3>${n}</h3><p>${d}</p></a>`).join('')}</div>`}
function home(){return `${header()}<main><section class="hero"><div class="wrap"><span class="eyebrow">Private browser tools</span><h1>Resize, Compress & Convert Photos Online</h1><p class="lead">Prepare photos, signatures and documents for online applications in seconds. Everything happens in your browser.</p><div class="actions"><a class="button" href="${route('photo-resizer')}">Start with Photo Resizer</a><a class="button secondary" href="${route('tools')}">Explore All Tools</a></div></div></section><section class="section wrap"><h2>Useful tools, without the upload</h2>${cards(tools.slice(0,9))}${ads('Homepage content')}</section><section class="section wrap"><h2>From file to ready-to-submit</h2><div class="steps"><div class="card step"><b>01</b>Choose a photo or signature.</div><div class="card step"><b>02</b>Crop and fine-tune it.</div><div class="card step"><b>03</b>Resize, convert or compress.</div><div class="card step"><b>04</b>Preview and download.</div></div></section><section class="section wrap"><div class="card"><h2>Designed for privacy</h2><p>${site.privacyMessage} Closing the tab removes your working files.</p><a class="button secondary" href="${route('privacy')}">Read our privacy approach</a></div></section></main>${footer()}`}
function toolPage(slug){const t=toolFor(slug), isPdf=slug.includes('pdf'), preset=slug.includes('pan-signature')?'pan-signature':slug.includes('pan-photo')?'pan-photo':slug.includes('passport')?'passport':slug.includes('visa')?'visa':'';return `${header()}<main class="wrap"><div class="crumb"><a href="${route()}">Home</a> / <a href="${route('tools')}">Tools</a> / ${t[1]}</div><div class="tool-layout"><section><span class="eyebrow">${t[2]} tool</span><h1 style="font-size:clamp(2rem,5vw,3.25rem)">${t[1]}</h1><p class="lead">${t[3]} Files stay on your device throughout the process.</p>${engine(slug,preset,isPdf)}<article class="content section"><h2>How to use ${t[1]}</h2><ol><li>Add an image using the upload area.</li><li>Set your dimensions, quality or target file size.</li><li>Process the file and check the preview before downloading.</li></ol><h2>Supported files</h2><p>JPG, JPEG, PNG and WEBP images are supported. ${isPdf?'The PDF builder uses your processed image copies locally.':''}</p><div class="faq"><h2>Frequently asked questions</h2><details><summary>Are my files uploaded?</summary><p>${site.privacyMessage}</p></details><details><summary>Can I use centimetres?</summary><p>Yes. At the selected DPI, pixels are calculated as centimetres ÷ 2.54 × DPI. Resizing changes pixels; it does not claim to alter image metadata.</p></details></div><h2>Related tools</h2>${cards(tools.filter(x=>x[0]!==slug).slice(0,3))}</article></section><aside class="side">${ads('Desktop sidebar')}<div class="card"><b>Private by design</b><p class="muted">No account, no server upload for image processing.</p></div></aside></div></main>${footer()}`}
function engine(slug,preset,isPdf){let p=presets.find(x=>x.slug===preset);return `<section class="card" id="engine" data-slug="${slug}" data-preset="${preset}"><div class="drop" id="drop"><b>Drop images here</b><p class="muted">or select JPG, PNG or WEBP · up to 20 MB each</p><input id="files" type="file" accept="image/jpeg,image/png,image/webp" ${isPdf?'multiple':''}/></div><p class="notice">${site.privacyMessage}</p><div id="originalInfo" class="muted"></div><div class="controls"><label>Width <input id="width" type="number" min="1" value="${p?presetPixels(p).width:''}" placeholder="Auto"/></label><label>Height <input id="height" type="number" min="1" value="${p?presetPixels(p).height:''}" placeholder="Auto"/></label><label>Unit <select id="unit"><option value="px">Pixels</option><option value="cm" ${p&&p.unit==='cm'?'selected':''}>Centimetres</option><option value="in" ${p&&p.unit==='in'?'selected':''}>Inches</option></select></label><label>DPI <input id="dpi" type="number" value="${p?.dpi||300}" min="72" max="600"/></label><label>Format <select id="format"><option value="image/jpeg">JPG</option><option value="image/png">PNG</option><option value="image/webp">WEBP</option></select></label><label>JPEG / WEBP quality <span class="range"><input id="quality" type="range" min="10" max="100" value="85"><output id="qualityOut">85</output></span></label><label>Target file size <select id="target"><option value="0">No target</option><option value="20">Under 20 KB</option><option value="50">Under 50 KB</option><option value="100">Under 100 KB</option><option value="200">Under 200 KB</option><option value="500">Under 500 KB</option></select></label><label>Custom target KB <input id="customTarget" type="number" min="1" placeholder="Optional"/></label><label>Rotation <select id="rotate"><option value="0">0°</option><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select></label><label>Crop / trim <select id="trim"><option value="none">Keep whole image</option><option value="square">Square crop</option><option value="white">Trim white signature margins</option></select></label><label>Brightness <input id="brightness" type="range" min="50" max="150" value="100"/></label><label>Contrast <input id="contrast" type="range" min="50" max="150" value="100"/></label><label>Background <input id="background" type="color" value="#ffffff"/></label><label class="full"><input id="gray" type="checkbox"/> Grayscale</label></div>${p?`<p class="notice">${p.name}: ${p.notes}</p>`:''}<div class="actions"><button class="button" id="process">${isPdf?'Create PDF':'Process image'}</button><button class="button secondary" id="reset">Reset</button></div><div id="message"></div><div id="previews" class="preview"></div><div id="results" class="results"></div></section>`}
function fmt(n){return n<1024?`${n} B`:`${(n/1024).toFixed(1)} KB`} function basename(n){return n.replace(/[^a-z0-9._-]/gi,'-').replace(/\.[^.]+$/,'')||'file'}
function loadImage(file){return new Promise((ok,bad)=>{const u=URL.createObjectURL(file),i=new Image();i.onload=()=>{URL.revokeObjectURL(u);ok(i)};i.onerror=bad;i.src=u})}
function cropSource(img, mode){let x=0,y=0,w=img.naturalWidth,h=img.naturalHeight;if(mode==='square'){const s=Math.min(w,h);x=(w-s)/2;y=(h-s)/2;w=h=s} return {x,y,w,h}}
async function renderImage(file,c){const img=await loadImage(file);let src=cropSource(img,c.trim); if(c.trim==='white'){const cv=document.createElement('canvas'),ct=cv.getContext('2d',{willReadFrequently:true});cv.width=img.naturalWidth;cv.height=img.naturalHeight;ct.drawImage(img,0,0);const d=ct.getImageData(0,0,cv.width,cv.height).data;let minX=cv.width,minY=cv.height,maxX=0,maxY=0;for(let y=0;y<cv.height;y+=2)for(let x=0;x<cv.width;x+=2){let z=(y*cv.width+x)*4;if(d[z]<245||d[z+1]<245||d[z+2]<245){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y)}}if(maxX>minX){const x=Math.max(0,minX-4),y=Math.max(0,minY-4),w=Math.min(cv.width-x,maxX-minX+8),h=Math.min(cv.height-y,maxY-minY+8);src={x,y,w,h}}}
 const { width: outW, height: outH }=calculateResizeDimensions({sourceWidth:src.w,sourceHeight:src.h,width:c.width,height:c.height,unit:c.unit,dpi:c.dpi,rotate:c.rotate});const rotated=+c.rotate%180!==0;if(outW*outH>40000000)throw Error('The image is too large for this device to process safely. Please choose a smaller image.');
 const cv=document.createElement('canvas');cv.width=outW;cv.height=outH;const ctx=cv.getContext('2d');ctx.fillStyle=c.background;ctx.fillRect(0,0,outW,outH);ctx.save();ctx.translate(outW/2,outH/2);ctx.rotate(+c.rotate*Math.PI/180);ctx.filter=`brightness(${c.brightness}%) contrast(${c.contrast}%) grayscale(${c.gray?100:0}%)`;const dw=rotated?outH:outW,dh=rotated?outW:outH;ctx.drawImage(img,src.x,src.y,src.w,src.h,-dw/2,-dh/2,dw,dh);ctx.restore();
 let quality=c.quality/100, blob=await new Promise(r=>cv.toBlob(r,c.format,quality));if(c.target && c.format!=='image/png'){let lo=.05,hi=quality,best=null;for(let n=0;n<8;n++){let q=(lo+hi)/2,b=await new Promise(r=>cv.toBlob(r,c.format,q));const step=nextQualityRange({low:lo,high:hi,candidateQuality:q,candidateBytes:b.size,targetBytes:c.target});if(step.bestQuality)best=b;lo=step.low;hi=step.high}blob=best||blob}if(!blob)throw Error('Unable to create the requested file.');return {blob,width:outW,height:outH,original:img};}
function makePdf(blob,w,h){return blob.arrayBuffer().then(ab=>{const jpg=new Uint8Array(ab);const enc=new TextEncoder();const parts=[],offsets=[0];let size=0;const push=x=>{const v=typeof x==='string'?enc.encode(x):x;parts.push(v);size+=v.length};push('%PDF-1.4\n');const obj=(n,body)=>{offsets[n]=size;push(`${n} 0 obj\n${body}\nendobj\n`)};obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=size;push(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);push(jpg);push('\nendstream\nendobj\n');const stream=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ`;obj(5,`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);const x=size;push('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)push(`${offsets[i].toString().padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})})}
function wireEngine(){const root=$('#engine');if(!root)return;let files=[];const input=$('#files'),drop=$('#drop'),message=$('#message'),preview=$('#previews'),results=$('#results');const change=e=>{const candidates=[...e]; files=candidates.filter(f=>validateImageFile(f).valid);const invalid=candidates.find(f=>!validateImageFile(f).valid);message.innerHTML=files.length?`<p class="notice">${files.length} image${files.length>1?'s':''} selected. ${files[0].name} · ${fmt(files[0].size)}${invalid?` · ${validateImageFile(invalid).message}`:''}</p>`:`<p class="notice error">${invalid?validateImageFile(invalid).message:'Choose JPG, PNG or WEBP images under 20 MB.'}</p>`};input.onchange=e=>change(e.target.files);['dragenter','dragover'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.add('drag')}));drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');change(e.dataTransfer.files)});$('#quality').oninput=e=>$('#qualityOut').value=e.target.value;
 $('#reset').onclick=()=>{input.value='';files=[];preview.innerHTML='';results.innerHTML='';message.innerHTML=''};$('#process').onclick=async()=>{if(!files.length)return change([]);const c={width:+$('#width').value,height:+$('#height').value,unit:$('#unit').value,dpi:+$('#dpi').value,format:$('#format').value,quality:+$('#quality').value,target:(+$('#customTarget').value||+$('#target').value)*1024,rotate:$('#rotate').value,trim:$('#trim').value,brightness:$('#brightness').value,contrast:$('#contrast').value,gray:$('#gray').checked,background:$('#background').value};const pdf=root.dataset.slug.includes('pdf');message.innerHTML='<p class="notice">Processing locally…</p>';preview.innerHTML='';results.innerHTML='';try{for(const file of files){const out=await renderImage(file,{...c,format:pdf?'image/jpeg':c.format});const final=pdf?await makePdf(out.blob,out.width,out.height):out.blob;const url=URL.createObjectURL(final), name=`${basename(file.name)}-filemango.${pdf?'pdf':final.type.split('/')[1].replace('jpeg','jpg')}`;const compression=((1-final.size/file.size)*100).toFixed(1);preview.insertAdjacentHTML('beforeend',`<figure><img src="${URL.createObjectURL(file)}" alt="Original ${file.name}"><figcaption>Original · ${file.name}<br>${fmt(file.size)}</figcaption></figure><figure>${pdf?'<div class="notice" style="margin:16px">PDF ready for download</div>':`<img src="${url}" alt="Processed preview">`}<figcaption>Processed · ${out.width} × ${out.height}px<br>${fmt(final.size)} ${pdf?'PDF':`· ${compression}% smaller`}</figcaption></figure>`);results.insertAdjacentHTML('beforeend',`<div class="result-row"><span>${name} · ${fmt(final.size)}${c.target?' · '+targetStatus(final.size,c.target):''}</span><a class="button accent" download="${name}" href="${url}">Download</a></div>`)}message.innerHTML=`<p class="notice">Done. ${files.length>1?'Download each result below.':'Your file is ready to download.'}</p>`}catch(e){message.innerHTML=`<p class="notice error">${e.message||'Unable to process this image. Please select a smaller image.'}</p>`}}}
function legal(page){const txt={about:['About FileMango','FileMango is an independent browser-based utility service for preparing images and documents.'],privacy:['Privacy','Your files are processed locally in your browser and are not uploaded to our server. We do not permanently store uploaded files because normal processing never sends them to a server. Optional anonymous analytics can be configured by the site owner without including file content.'],terms:['Terms of use','Use the tools at your discretion and verify every output against the requirements of the organization receiving it.'],contact:['Contact',`For feedback or support, contact ${site.contactEmail}.`],disclaimer:['Disclaimer','This website is an independent utility service and is not affiliated with or endorsed by any government authority unless explicitly stated. Government and application specifications can change; verify the latest requirements on the official application website.']}[page];return `${header()}<main class="wrap legal"><h1>${txt[0]}</h1><p class="lead">${txt[1]}</p></main>${footer()}`}
function render(){let path=location.pathname.split('/').filter(Boolean).at(-1)||'';if(path==='kanhaiya-convertor')path='';let html=path===''?home():path==='tools'?`${header()}<main class="wrap section"><h1 style="font-size:3rem">All tools</h1>${cards()}</main>${footer()}`:['about','privacy','terms','contact','disclaimer'].includes(path)?legal(path):toolPage(path);app.innerHTML=html;wireEngine();window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
